--
-- Table structure for table `date_eras`
--

DROP TABLE IF EXISTS `date_eras`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `date_eras` (
  `ind` int NOT NULL AUTO_INCREMENT,
  `id` int NOT NULL,
  `can_name` varchar(8) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `dyn_id` smallint NOT NULL,
  `ruler_id` int DEFAULT NULL,
  `start_year` smallint DEFAULT NULL,
  `end_year` smallint DEFAULT NULL,
  `start_jdn` double DEFAULT NULL,
  `end_jdn` double DEFAULT NULL,
  `dila_id` int DEFAULT NULL,
  `source` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `created_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `creation_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `modified_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mod_date` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`ind`),
  KEY `dyn_id` (`dyn_id`),
  KEY `emp_person_id` (`ruler_id`),
  CONSTRAINT `date_eras_ibfk_1` FOREIGN KEY (`dyn_id`) REFERENCES `date_dynasties` (`id`),
  CONSTRAINT `date_eras_ibfk_2` FOREIGN KEY (`ruler_id`) REFERENCES `person` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

